//! Unit tests pinning the ref-action payloads' wire forms.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use super::{RefRequest, ScrollRequest, SelectRequest, SetValueRequest, TypeRequest};
use crate::vocabulary::Direction;
use serde_json::json;

#[test]
fn a_bare_ref_request_needs_only_the_ref() {
    let request: RefRequest =
        serde_json::from_value(json!({ "ref_id": "@s1:e2" })).expect("it decodes");

    assert_eq!(request, RefRequest::new("@s1:e2"));
    assert!(request.snapshot_id.is_none());
    assert!(request.timeout_ms.is_none());
}

#[test]
fn a_ref_request_serializes_its_absent_fields_as_null() {
    // `#[serde(default)]` on the struct makes them optional inbound; they stay
    // present outbound so a reader can see the request was fully specified.
    let value = serde_json::to_value(RefRequest::new("@s1:e2")).expect("it serializes");

    assert_eq!(
        value,
        json!({ "ref_id": "@s1:e2", "snapshot_id": null, "timeout_ms": null })
    );
}

#[test]
fn a_type_request_carries_its_text_verbatim() {
    let request: TypeRequest =
        serde_json::from_value(json!({ "ref_id": "@s1:e2", "text": "  spaced  " }))
            .expect("it decodes");

    // No trimming in the contract: what the caller sent is what is typed.
    assert_eq!(request.text, "  spaced  ");
}

#[test]
fn set_value_and_select_share_a_shape_but_not_a_type() {
    let set_value: SetValueRequest =
        serde_json::from_value(json!({ "ref_id": "@s1:e2", "value": "42" })).expect("it decodes");
    let select: SelectRequest =
        serde_json::from_value(json!({ "ref_id": "@s1:e3", "value": "Monday" }))
            .expect("it decodes");

    assert_eq!(set_value.value, "42");
    assert_eq!(select.value, "Monday");
}

#[test]
fn a_scroll_request_omits_its_absent_optional_fields() {
    let value = serde_json::to_value(ScrollRequest::new("@s1:e4", Direction::Down, 3))
        .expect("it serializes");

    assert_eq!(
        value,
        json!({ "ref_id": "@s1:e4", "direction": "Down", "amount": 3 })
    );
}

#[test]
fn a_scroll_request_round_trips_with_every_field_set() {
    let request = ScrollRequest {
        snapshot_id: Some("s1".to_owned()),
        timeout_ms: Some(2_000),
        ..ScrollRequest::new("@s1:e4", Direction::Left, 10)
    };

    let decoded: ScrollRequest =
        serde_json::from_value(serde_json::to_value(&request).expect("it serializes"))
            .expect("it decodes");

    assert_eq!(decoded, request);
}

# Implementation plans

Plans turn an accepted specification into a reviewable sequence of small,
verifiable changes. They explain how to build the behavior; the linked
specification remains the source of truth for what the behavior must be.

Use the same kebab-case stem as the specification. A useful plan includes:

- a link to the accepted specification;
- the goal, non-goals, and assumptions relevant to implementation;
- ordered tasks with exact file paths;
- a failing test before each behavior change;
- the minimal implementation needed to pass that test;
- documentation and public-export updates;
- focused and full verification commands;
- a completion checklist updated as tasks land.

Prefer tasks that can be implemented and reviewed independently. Include short
code snippets when they remove ambiguity, but do not paste entire future files
into the plan.

See [`desktop-module-contract.md`](desktop-module-contract.md) for a worked
example.

//! Integration tests against this crate's public API.
//!
//! These exercise the crate the way a dependent would: only what `src/lib.rs`
//! exports, with no reach into private items. They are the regression suite for
//! the crate's public contract — the surface a host binds to and the surface
//! that cannot change without a version bump.
//!
//! Nothing here drives a real application. Every assertion holds on a machine
//! with no permission granted, no display server, and nothing running, because
//! CI is such a machine and a test that only passes on a developer's desktop is
//! a test nobody runs.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use tinydesktop::{
    CONTRACT_VERSION, Desktop, ENVELOPE_VERSION, ElementProperty, GetRequest, INTERFACE,
    ListAppsRequest, METHODS, OBJECT_PATH, PermissionsRequest, RefRequest, SnapshotRequest,
    WaitRequest, is_compatible, names,
};

#[test]
fn the_crate_re_exports_the_contract_rather_than_redefining_it() {
    // The same type by both paths, not a structural twin: a host may depend on
    // `tinydesktop-bus` alone and hand its values straight to this crate.
    let request: tinydesktop_bus::RefRequest = RefRequest::new("@s1:e2");
    let reply = Desktop::new().click(request);

    assert_eq!(reply.command, "click");
    assert_eq!(INTERFACE, tinydesktop_bus::INTERFACE);
    assert_eq!(OBJECT_PATH, tinydesktop_bus::OBJECT_PATH);
    assert_eq!(METHODS, tinydesktop_bus::METHODS);
}

#[test]
fn the_shipped_contract_binds_to_itself() {
    assert!(is_compatible(CONTRACT_VERSION));
    assert_eq!(CONTRACT_VERSION, (1, 1));
}

#[test]
fn the_module_serves_every_member_the_contract_names() {
    assert_eq!(METHODS.len(), 56);
    assert!(METHODS.contains(&names::methods::SNAPSHOT));
    assert!(METHODS.contains(&names::methods::PERMISSIONS));
}

#[test]
fn version_succeeds_on_an_unconfigured_machine() {
    let reply = Desktop::new().version();

    assert!(reply.ok);
    assert_eq!(reply.version, ENVELOPE_VERSION);
    assert_eq!(reply.command, "version");
    let data = reply.data.expect("a successful reply carries data");
    assert_eq!(data["os"], serde_json::json!(std::env::consts::OS));
}

#[test]
fn a_reply_carries_data_or_an_error_but_never_both_and_never_neither() {
    // Every member on the same envelope contract, whatever this machine
    // happens to allow.
    let replies = [
        Desktop::new().version(),
        Desktop::new().list_apps(ListAppsRequest::default()),
        Desktop::new().permissions(PermissionsRequest::default()),
        Desktop::new().snapshot(SnapshotRequest::default()),
        Desktop::new().get(GetRequest::new("@s1:e2", ElementProperty::Role)),
    ];

    for reply in replies {
        assert_eq!(reply.version, ENVELOPE_VERSION);
        assert!(!reply.command.is_empty());
        assert_eq!(reply.ok, reply.data.is_some());
        assert_eq!(!reply.ok, reply.error.is_some());
    }
}

#[test]
fn a_failed_reply_carries_a_machine_readable_code() {
    // An empty ref cannot resolve anywhere, so this fails on every platform —
    // with a code rather than only a sentence.
    let reply = Desktop::new().get(GetRequest::new("", ElementProperty::Role));

    let error = reply.error.expect("an empty ref cannot succeed");
    assert!(!error.code.is_empty());
    assert!(
        error
            .code
            .chars()
            .all(|c| c.is_ascii_uppercase() || c == '_')
    );
    assert!(!error.message.is_empty());
}

#[test]
fn a_sleep_is_the_one_wait_that_needs_nothing_granted() {
    let reply = Desktop::new().wait(WaitRequest::sleep(1));

    assert!(reply.ok, "a sleep touches no other application");
    assert_eq!(reply.data.expect("data")["waited_ms"], serde_json::json!(1));
}

#[test]
fn a_configured_desktop_reports_what_it_was_configured_with() {
    let desktop = Desktop::from_config(&serde_json::json!({
        "session_id": "public-api-test",
        "headed": true,
    }))
    .expect("a valid configuration");

    assert_eq!(desktop.session_id(), Some("public-api-test"));
    assert!(desktop.is_headed());
    assert!(!desktop.is_tracing());
}

#[test]
fn an_invalid_configuration_is_an_error_a_caller_can_match_on() {
    let error = Desktop::from_config(&serde_json::json!({ "headed": 1 }))
        .expect_err("a number is not a boolean");

    assert!(matches!(
        error,
        tinydesktop::Error::ConfigFieldType {
            field: "headed",
            ..
        }
    ));
}

#[test]
fn the_reserved_hold_members_fail_closed_and_say_what_to_use_instead() {
    let reply = Desktop::new().mouse_down(tinydesktop::HoldMouseRequest::default());

    assert!(!reply.ok, "a stateless module cannot hold a button down");
    let error = reply.error.expect("a refusal carries an error");
    assert!(
        error.suggestion.is_some() || !error.message.is_empty(),
        "the refusal must say what to do instead"
    );
}

//! Tests for deterministic Jev desktop-control policy.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::{
    collections::{BTreeMap, VecDeque},
    sync::{Arc, Mutex},
    time::Duration,
};

use super::{
    AgentBackend, Evaluator, JevRuntime, execute_desktop, internal_error,
    policy::{
        ACT, DESTRUCTIVE, FLOOR, action_space, choice, deterministic_destructive,
        exact_named_match, gate_with_evidence, noul, parse_operation, playing_goal_satisfied,
        positional_match, request, rerank_request, shortlist, target,
    },
    provider_error, reason, resolve_intent, resolve_intent_with, response as agent_response,
    run_goal, run_goal_with,
    screen::{Candidate, Screen, describe, fingerprint, observe, parse_reply},
    target_payload, visible_completion,
};
use serde_json::json;
use tinydesktop_bus::{
    DesktopResponse, JevConfig, JevDecisionKind, JevOperation, JevProvider, JevStopReason,
    RunGoalRequest,
};
use tinyjevclient::{Answer, ChoiceAnswer};

#[test]
fn execution_gates_on_selected_probability_not_distribution_concentration() {
    let answer = Answer::Choice(ChoiceAnswer {
        choice: "liked".to_owned(),
        probabilities: BTreeMap::from([("liked".to_owned(), 0.91), ("other".to_owned(), 0.09)]),
        confidence: 0.41,
    });

    assert_eq!(choice(Some(&answer)), Some(("liked", 0.91)));
}

#[test]
fn destructive_actions_always_require_confirmation() {
    assert_eq!(
        gate_with_evidence(JevOperation::Click, 0.99, DESTRUCTIVE, false),
        JevDecisionKind::ConfirmationRequired
    );
}

#[test]
fn only_safe_confident_actions_are_executable() {
    assert_eq!(
        gate_with_evidence(JevOperation::Click, ACT, DESTRUCTIVE - 0.01, false),
        JevDecisionKind::Act
    );
    assert_eq!(
        gate_with_evidence(JevOperation::Click, FLOOR - 0.01, 0.0, false),
        JevDecisionKind::Abstain
    );
}

#[test]
fn an_exact_multiword_accessible_name_is_strong_identity_evidence() {
    let candidate = Candidate {
        name: Some("Liked Songs".to_owned()),
        ..Candidate::default()
    };
    assert!(exact_named_match(
        "open Liked Songs and play the first track",
        Some(&candidate)
    ));
    assert_eq!(
        gate_with_evidence(JevOperation::Click, 0.52, 0.05, true),
        JevDecisionKind::Act
    );
}

#[test]
fn topmost_play_target_is_strong_positional_evidence() {
    let top = Candidate {
        ref_id: "@s:e1".to_owned(),
        name: Some("Play First Song by Artist".to_owned()),
        bounds: Some(serde_json::json!({"x": 10.0, "y": 100.0})),
        ..Candidate::default()
    };
    let lower = Candidate {
        ref_id: "@s:e2".to_owned(),
        name: Some("Play Second Song by Artist".to_owned()),
        bounds: Some(serde_json::json!({"x": 10.0, "y": 160.0})),
        ..Candidate::default()
    };
    let peers = BTreeMap::from([("1".to_owned(), top.clone()), ("2".to_owned(), lower)]);

    assert!(positional_match(
        "play the topmost song",
        Some(&top),
        Some(&peers)
    ));
    assert_eq!(
        gate_with_evidence(JevOperation::Click, 0.49, 0.05, true),
        JevDecisionKind::Act
    );
}

#[test]
fn visible_pause_on_the_top_track_completes_a_playing_goal() {
    let mut screen = two_candidate_screen();
    screen.candidates[0].name = Some("Pause First Song by Artist".to_owned());
    assert!(playing_goal_satisfied(
        "ensure the topmost song is playing",
        &screen
    ));
    assert!(visible_completion("ensure the topmost song is playing", &screen).is_some());
    assert!(!playing_goal_satisfied("open the playlist", &screen));
}

#[test]
fn terminal_operations_are_not_treated_as_actions() {
    assert_eq!(
        gate_with_evidence(JevOperation::Done, 1.0, 1.0, false),
        JevDecisionKind::Done
    );
    assert_eq!(
        gate_with_evidence(JevOperation::Blocked, 1.0, 1.0, false),
        JevDecisionKind::Blocked
    );
    assert_eq!(
        gate_with_evidence(JevOperation::Done, ACT - 0.01, 0.0, false),
        JevDecisionKind::Abstain
    );
}

#[test]
fn deterministic_risk_and_identity_checks_fail_closed() {
    let delete = Candidate {
        name: Some("Delete account".to_owned()),
        ..Candidate::default()
    };
    assert!(deterministic_destructive(
        "continue",
        JevOperation::Click,
        Some(&delete)
    ));
    assert!(!deterministic_destructive(
        "continue",
        JevOperation::Scroll,
        Some(&delete)
    ));
    let candidate = Candidate {
        name: Some("Liked Songs".to_owned()),
        ..Candidate::default()
    };
    assert!(!exact_named_match("open Disliked Songs", Some(&candidate)));
    let decorated = Candidate {
        name: Some("Liked Songs Pinned Downloaded Playlist".to_owned()),
        ..Candidate::default()
    };
    assert!(exact_named_match("open Liked Songs", Some(&decorated)));
}

#[derive(Clone)]
struct FakeBackend {
    screens: Arc<Mutex<VecDeque<Screen>>>,
    operations: Arc<Mutex<Vec<JevOperation>>>,
    fail_execute: bool,
}

impl AgentBackend for FakeBackend {
    fn observe(&self, _app: &str, _root: Option<&str>) -> Result<Screen, Box<DesktopResponse>> {
        self.screens
            .lock()
            .expect("screen lock")
            .pop_front()
            .ok_or_else(|| {
                Box::new(DesktopResponse::err(
                    "snapshot",
                    tinydesktop_bus::DesktopError::new("EMPTY", "no screen"),
                ))
            })
    }

    fn execute(
        &self,
        operation: JevOperation,
        _target: Option<Candidate>,
        _text: Option<String>,
    ) -> DesktopResponse {
        self.operations
            .lock()
            .expect("operation lock")
            .push(operation);
        if self.fail_execute {
            DesktopResponse::err(
                "fake",
                tinydesktop_bus::DesktopError::new("ACTION_FAILED", "fake failure"),
            )
        } else {
            DesktopResponse::ok("fake", json!({"delivery": "delivered_verified"}))
        }
    }
}

fn clickable_screen() -> Screen {
    Screen {
        app: "Spotify".to_owned(),
        window: Some("Liked Songs".to_owned()),
        surface: "window".to_owned(),
        root: None,
        candidates: vec![Candidate {
            ref_id: "@s1:e1".to_owned(),
            role: "button".to_owned(),
            name: Some("Play First Song by Artist".to_owned()),
            available_actions: vec!["Click".to_owned()],
            bounds: Some(json!({"x": 10.0, "y": 100.0})),
            ..Candidate::default()
        }],
    }
}

fn two_candidate_screen() -> Screen {
    let mut screen = clickable_screen();
    screen.candidates.push(Candidate {
        ref_id: "@s1:e2".to_owned(),
        role: "button".to_owned(),
        name: Some("Play Second Song by Artist".to_owned()),
        available_actions: vec!["Click".to_owned()],
        bounds: Some(json!({"x": 10.0, "y": 160.0})),
        ..Candidate::default()
    });
    screen
}

fn response(operation: &str, probability: f64, target: &str) -> tinyjevclient::EvaluationResult {
    response_with(operation, probability, target, 0.9, 0.05)
}

fn response_with(
    operation: &str,
    probability: f64,
    target: &str,
    selected_target_probability: f64,
    destructive: f64,
) -> tinyjevclient::EvaluationResult {
    let remainder = (1.0 - probability) / 3.0;
    let target_probability = if target == "1" {
        selected_target_probability
    } else {
        1.0 - selected_target_probability
    };
    evaluation(json!({
        "model": "typesafe/jev-1.13-20260917",
        "answers": {
            "operation": {
                "type": "choice", "choice": operation, "confidence": 0.4,
                "probabilities": {
                    "CLICK": if operation == "CLICK" { probability } else { remainder },
                    "WAIT": if operation == "WAIT" { probability } else { remainder },
                    "DONE": if operation == "DONE" { probability } else { remainder },
                    "BLOCKED": if operation == "BLOCKED" { probability } else { remainder }
                }
            },
            "click_target": {
                "type": "choice", "choice": target, "confidence": 0.4,
                "probabilities": {"1": target_probability, "none": 1.0 - target_probability}
            },
            "destructive": {"type": "noul", "noul": destructive}
        },
        "usage": {"input_tokens": 10, "output_tokens": 2}
    }))
}

fn evaluation(value: serde_json::Value) -> tinyjevclient::EvaluationResult {
    let response = serde_json::from_value(value).expect("mock response decodes");
    tinyjevclient::EvaluationResult {
        response,
        request_id: Some("mock-request".to_owned()),
        attempts: 1,
        latency: Duration::from_millis(1),
    }
}

struct MockEvaluator {
    results: Mutex<VecDeque<tinyjevclient::EvaluationResult>>,
}

impl Evaluator for MockEvaluator {
    fn evaluate<'a>(
        &'a self,
        _request: &'a tinyjevclient::EvaluationRequest,
    ) -> std::pin::Pin<
        Box<
            dyn std::future::Future<
                    Output = Result<
                        tinyjevclient::EvaluationResult,
                        tinyjevclient::EvaluationFailure,
                    >,
                > + Send
                + 'a,
        >,
    > {
        Box::pin(async move {
            Ok(self
                .results
                .lock()
                .expect("evaluation lock")
                .pop_front()
                .expect("mock evaluation"))
        })
    }
}

fn runtime(results: Vec<tinyjevclient::EvaluationResult>) -> JevRuntime {
    JevRuntime {
        client: Arc::new(MockEvaluator {
            results: Mutex::new(VecDeque::from(results)),
        }),
        configuration: tinydesktop_bus::JevConfiguration {
            provider: tinydesktop_bus::JevProvider::OpenRouter,
            model: "jev-latest".to_owned(),
            endpoint_url: None,
        },
    }
}

fn backend(screen_count: usize) -> (FakeBackend, Arc<Mutex<Vec<JevOperation>>>) {
    let operations = Arc::new(Mutex::new(Vec::new()));
    (
        FakeBackend {
            screens: Arc::new(Mutex::new(VecDeque::from(
                (0..screen_count)
                    .map(|_| clickable_screen())
                    .collect::<Vec<_>>(),
            ))),
            operations: Arc::clone(&operations),
            fail_execute: false,
        },
        operations,
    )
}

#[tokio::test]
async fn goal_loop_executes_a_safe_choice_then_stops_done() {
    let runtime = runtime(vec![
        response("CLICK", 0.9, "1"),
        response("DONE", 0.9, "none"),
    ]);
    let (backend, operations) = backend(3);
    let reply = run_goal_with(
        backend,
        runtime,
        RunGoalRequest {
            app: "Spotify".to_owned(),
            goal: "play the topmost song".to_owned(),
            max_steps: 3,
            max_model_calls: 3,
            ..RunGoalRequest::default()
        },
    )
    .await;
    assert!(reply.ok);
    let result: tinydesktop_bus::JevRunResult =
        serde_json::from_value(reply.data.expect("run returns data")).expect("result decodes");
    assert_eq!(result.stop, JevStopReason::Done);
    assert_eq!(result.turns.len(), 1);
    assert_eq!(
        *operations.lock().expect("operation lock"),
        vec![JevOperation::Click]
    );
    assert_eq!((result.metrics.calls, result.metrics.attempts), (2, 2));
}

async fn run_case(
    bodies: Vec<tinyjevclient::EvaluationResult>,
    screen_count: usize,
    max_steps: u32,
    max_model_calls: u32,
    goal: &str,
) -> tinydesktop_bus::JevRunResult {
    let runtime = runtime(bodies);
    let (backend, _) = backend(screen_count);
    let reply = run_goal_with(
        backend,
        runtime,
        RunGoalRequest {
            app: "Spotify".to_owned(),
            goal: goal.to_owned(),
            max_steps,
            max_model_calls,
            ..RunGoalRequest::default()
        },
    )
    .await;
    serde_json::from_value(reply.data.expect("run returns data")).expect("result decodes")
}

#[tokio::test]
async fn goal_loop_reports_terminal_policy_outcomes() {
    let blocked = run_case(
        vec![response("BLOCKED", 0.9, "none")],
        1,
        3,
        3,
        "impossible",
    )
    .await;
    assert_eq!(blocked.stop, JevStopReason::Blocked);

    let confirmation = run_case(
        vec![response_with("CLICK", 0.9, "1", 0.9, 0.9)],
        1,
        3,
        3,
        "play the topmost song",
    )
    .await;
    assert_eq!(confirmation.stop, JevStopReason::ConfirmationRequired);

    let no_target = run_case(
        vec![response("CLICK", 0.9, "none")],
        1,
        3,
        3,
        "activate something",
    )
    .await;
    assert_eq!(no_target.stop, JevStopReason::LowConfidence);
}

#[tokio::test]
async fn goal_loop_enforces_action_model_and_stall_budgets() {
    let action_budget = run_case(
        vec![response("CLICK", 0.9, "1")],
        2,
        1,
        3,
        "play the topmost song",
    )
    .await;
    assert_eq!(action_budget.stop, JevStopReason::ActionBudget);

    let model_budget = run_case(
        vec![response("CLICK", 0.9, "1")],
        2,
        4,
        1,
        "play the topmost song",
    )
    .await;
    assert_eq!(model_budget.stop, JevStopReason::ModelBudget);

    let stalled = run_case(
        vec![
            response("CLICK", 0.9, "1"),
            response("CLICK", 0.9, "1"),
            response("CLICK", 0.9, "1"),
        ],
        6,
        4,
        4,
        "play the topmost song",
    )
    .await;
    assert_eq!(stalled.stop, JevStopReason::Stalled);
}

#[tokio::test]
async fn goal_loop_preserves_failed_actions_and_post_action_observation_failures() {
    let failed_runtime = runtime(vec![response("CLICK", 0.9, "1")]);
    let operations = Arc::new(Mutex::new(Vec::new()));
    let failed_backend = FakeBackend {
        screens: Arc::new(Mutex::new(VecDeque::from([clickable_screen()]))),
        operations: Arc::clone(&operations),
        fail_execute: true,
    };
    let failed = run_goal_with(
        failed_backend,
        failed_runtime,
        RunGoalRequest {
            app: "Spotify".to_owned(),
            goal: "play the topmost song".to_owned(),
            ..RunGoalRequest::default()
        },
    )
    .await;
    let failed: tinydesktop_bus::JevRunResult =
        serde_json::from_value(failed.data.expect("failed run data")).expect("result decodes");
    assert_eq!(failed.stop, JevStopReason::ActionFailed);
    assert_eq!(failed.turns.len(), 1);
    assert!(!failed.turns[0].ok);

    let observation_runtime = runtime(vec![response("CLICK", 0.9, "1")]);
    let (backend, _) = backend(1);
    let lost_screen = run_goal_with(
        backend,
        observation_runtime,
        RunGoalRequest {
            app: "Spotify".to_owned(),
            goal: "play the topmost song".to_owned(),
            ..RunGoalRequest::default()
        },
    )
    .await;
    let lost_screen: tinydesktop_bus::JevRunResult =
        serde_json::from_value(lost_screen.data.expect("lost screen data"))
            .expect("result decodes");
    assert_eq!(lost_screen.stop, JevStopReason::ActionFailed);
    assert_eq!(lost_screen.turns.len(), 1);
}

#[test]
fn screen_parsing_filters_disabled_nodes_and_builds_descriptions() {
    let reply = DesktopResponse::ok(
        "snapshot",
        json!({
            "app": "Spotify", "window": {"title": "Liked Songs"},
            "tree": {"role": "window", "children": [
